<template>
  <div class="page-incident-list">
    <CrudToolbar :title="t('incidents.title')" :can-create="false" />

    <el-card>
      <div class="filter-bar">
        <el-select v-model="filters.status" :placeholder="t('common.status')" clearable style="width: 140px">
          <el-option :label="t('incidents.statusOpen')" value="open" />
          <el-option :label="t('incidents.statusAcknowledged')" value="acknowledged" />
          <el-option :label="t('incidents.statusResolved')" value="resolved" />
          <el-option :label="t('incidents.statusClosed')" value="closed" />
        </el-select>
        <el-select v-model="filters.severity" :placeholder="t('common.severityLabel')" clearable style="width: 140px">
          <el-option :label="t('common.critical')" value="critical" />
          <el-option :label="t('common.warning')" value="warning" />
          <el-option :label="t('common.info')" value="info" />
        </el-select>
        <el-button type="primary" @click="onSearch">{{ t('common.query') }}</el-button>
        <el-button @click="onReset">{{ t('common.reset') }}</el-button>
      </div>

      <DataTable
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :data="incidents"
        :loading="loading"
        :server-side="true"
        :total="total"
        @row-click="onRowClick"
      >
        <el-table-column prop="id" label="ID" width="80" />
        <el-table-column prop="title" :label="t('incidents.titleColumn')" min-width="200" />
        <el-table-column prop="severity" :label="t('common.severityLabel')" width="100">
          <template #default="{ row }">
            <StatusTag :status="row.severity" type="severity" />
          </template>
        </el-table-column>
        <el-table-column prop="status" :label="t('common.status')" width="110">
          <template #default="{ row }">
            <StatusTag :status="row.status" type="incident" />
          </template>
        </el-table-column>
        <el-table-column prop="started_at" :label="t('incidents.startedAt')" min-width="160">
          <template #default="{ row }">
            {{ formatTime(row.started_at) }}
          </template>
        </el-table-column>
        <el-table-column prop="assigned_to" :label="t('incidents.assignee')" width="110">
          <template #default="{ row }">
            {{ row.assigned_to || '-' }}
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="300" fixed="right">
          <template #default="{ row }">
            <el-button
              link
              type="primary"
              size="small"
              :disabled="row.status !== 'open'"
              @click.stop="onAck(row)"
            >
              {{ t('incidents.ack') }}
            </el-button>
            <el-button
              link
              type="success"
              size="small"
              :disabled="row.status === 'resolved' || row.status === 'closed'"
              @click.stop="onResolve(row)"
            >
              {{ t('incidents.resolve') }}
            </el-button>
            <el-button
              link
              type="info"
              size="small"
              :disabled="row.status === 'closed'"
              @click.stop="onClose(row)"
            >
              {{ t('common.close') }}
            </el-button>
            <el-button
              v-if="authStore.isAdmin"
              link
              type="warning"
              size="small"
              @click.stop="onAssign(row)"
            >
              {{ t('incidents.assign') }}
            </el-button>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import {
  acknowledgeIncident,
  closeIncident,
  getIncidents,
  resolveIncident,
  updateIncident,
  type IncidentRead,
  type IncidentSeverity,
  type IncidentStatus,
} from '@/api/incidents'
import { useRealtimeRefresh } from '@/composables/useRealtimeRefresh'
import { useListQuery } from '@/composables/useListQuery'
import StatusTag from '@/components/common/StatusTag.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const authStore = useAuthStore()
const router = useRouter()

const incidents = ref<IncidentRead[]>([])
const total = ref(0)
const loading = ref(false)

const { page, pageSize, filters, resetFilters } = useListQuery({
  defaults: {
    status: '' as IncidentStatus | '',
    severity: '' as IncidentSeverity | '',
  },
  parse: (q) => ({
    status: (q.status as IncidentStatus) || '',
    severity: (q.severity as IncidentSeverity) || '',
  }),
  serialize: (f) => ({
    status: f.status || undefined,
    severity: f.severity || undefined,
  }),
})

async function loadIncidents() {
  loading.value = true
  try {
    const response = await getIncidents({
      page: page.value,
      page_size: pageSize.value,
      status: (filters.status || undefined) as IncidentStatus | undefined,
      severity: (filters.severity || undefined) as IncidentSeverity | undefined,
    })
    incidents.value = response.items
    total.value = response.total
  } catch (error) {
    showError(error, t('incidents.loadFailed'))
  } finally {
    loading.value = false
  }
}

function onSearch() {
  page.value = 1
}

function onReset() {
  resetFilters()
}

function onRowClick(row: IncidentRead) {
  router.push(`/incidents/${row.id}`)
}

async function onAck(row: IncidentRead) {
  try {
    await acknowledgeIncident(row.id)
    ElMessage.success(t('incidents.acked'))
    loadIncidents()
  } catch (error) {
    showError(error, t('incidents.ackFailed'))
  }
}

async function onResolve(row: IncidentRead) {
  try {
    await resolveIncident(row.id)
    ElMessage.success(t('incidents.resolved'))
    loadIncidents()
  } catch (error) {
    showError(error, t('incidents.resolveFailed'))
  }
}

async function onClose(row: IncidentRead) {
  try {
    await closeIncident(row.id)
    ElMessage.success(t('incidents.closed'))
    loadIncidents()
  } catch (error) {
    showError(error, t('incidents.closeFailed'))
  }
}

async function onAssign(row: IncidentRead) {
  try {
    const { value } = await ElMessageBox.prompt(t('incidents.assignPrompt'), t('incidents.assignTitle'), {
      confirmButtonText: t('common.confirm'),
      cancelButtonText: t('common.cancel'),
      inputPattern: /^\d+$/,
      inputErrorMessage: t('incidents.assignInputError'),
    })
    await updateIncident(row.id, { assigned_to: Number(value) })
    ElMessage.success(t('incidents.assigned'))
    loadIncidents()
  } catch (error: any) {
    if (error === 'cancel') return
    showError(error, t('incidents.assignFailed'))
  }
}

function formatTime(value: string) {
  return new Date(value).toLocaleString()
}

useRealtimeRefresh(loadIncidents, ['incidents'], { notifyEventTypes: ['incident.created'] })

watch(
  () => ({ page: page.value, pageSize: pageSize.value, filters }),
  loadIncidents,
  { deep: true, immediate: true }
)
</script>

<style scoped>
.filter-bar {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
}
</style>
